parameters.jsCode:
// Extract incoming job metadata and attachments
const body = $input.first().json.body || $input.first().json;

const attachments = (body.attachments || []).map(att => ({
  filename: att.filename,
  mimeType: att.file_type,
  data: att.content_base64
}));

const subject = `Havells Pre-Dispatch Inspection (PDI) Reports - Job ${body.job_code || ''} [${body.product_type || 'Equipment'}]`;
const htmlBody = `
<div style="font-family: Arial, sans-serif; color: #333;">
  <h2 style="color: #B22222;">HAVELLS INDIA LIMITED - Quality Assurance Dept</h2>
  <p>Dear ${body.customer_name || 'Customer'},</p>
  <p>Please find attached the official Pre-Delivery Inspection (PDI) report(s) for your recent order.</p>
  <table border="1" cellpadding="6" style="border-collapse: collapse;">
    <tr><td><strong>Job Reference:</strong></td><td>${body.job_code}</td></tr>
    <tr><td><strong>Product:</strong></td><td>${body.product_type} (${body.product_number})</td></tr>
    <tr><td><strong>Lot Size:</strong></td><td>${body.lot_size} Units</td></tr>
    <tr><td><strong>Inspection Status:</strong></td><td style="color: green; font-weight: bold;">APPROVED / PASS</td></tr>
  </table>
  <p>The editable source Excel records and official PDF copies are attached.</p>
  <p>Best regards,<br/><strong>Havells QA & Dispatch Team</strong></p>
</div>
`;

return [{
  json: {
    toEmail: body.customer_email,
    customerName: body.customer_name,
    subject: subject,
    html: htmlBody,
    jobCode: body.job_code,
    attachmentsCount: attachments.length
  },
  binary: attachments.reduce((acc, att, idx) => {
    acc[`attachment_${idx}`] = {
      data: att.data,
      fileName: att.filename,
      mimeType: att.mimeType
    };
    return acc;
  }, {})
}];

